css:
@font-face{font-family:"Pretendard";font-weight:400;font-display:swap;src:url("vendor/pretendard-1.3.9/woff2/Pretendard-Regular.woff2") format("woff2")}
@font-face{font-family:"Pretendard";font-weight:500;font-display:swap;src:url("vendor/pretendard-1.3.9/woff2/Pretendard-Medium.woff2") format("woff2")}
@font-face{font-family:"Pretendard";font-weight:600;font-display:swap;src:url("vendor/pretendard-1.3.9/woff2/Pretendard-SemiBold.woff2") format("woff2")}
@font-face{font-family:"Pretendard";font-weight:700;font-display:swap;src:url("vendor/pretendard-1.3.9/woff2/Pretendard-Bold.woff2") format("woff2")}

:root{

  --shade:#040303; --white:#FFFFFF; --red:#EE2F2B; --red-flow:#DC463B; --red-text:#EF4036; --red-dot:#EF4445; --red-deep:#7F2325;
  --yellow:#F8ED30; --yellow-head:#F2E542; --yellow-green:#D7DF23; --mint:#9DC9BB; --green:#00BD71; --teal:#08A79E;
  --violet:#7D5EA8; --navy:#2E3092; --box:#3E3C3C; --band:#202621; --ring:#E6E7E8; --link:#F2F2F3; --grey:#BCBEC0;
  --orange:#EDA568; --brown:#A84F3A; --ink-dark:#060303;

  --ui-bg:rgba(14,18,17,.86); --ui-bg-solid:#0e1211; --ui-line:rgba(255,255,255,.09); --ui-ink:#e9ecea; --ui-dim:#9aa3a0; --ui-faint:#8a9491;
  --ui-accent:#F8ED30; --ui-radius:10px;
  --font-display:"Black Han Sans","Do Hyeon","Pretendard",system-ui,sans-serif;
  --font-body:"Pretendard","Apple SD Gothic Neo","Malgun Gothic",system-ui,sans-serif;
}
*{box-sizing:border-box}
html,body{margin:0;height:100%;background:#050605;color:var(--ui-ink);font-family:var(--font-body);-webkit-font-smoothing:antialiased;overflow:hidden}
button,select,input{font:inherit;color:inherit}
#app{position:fixed;inset:0}
#map{position:absolute;inset:0;background:#070908}
#ov{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;overflow:visible;font-family:var(--font-body)}
#ov .hit{pointer-events:visiblePainted;cursor:pointer}
#ov .hit-box{pointer-events:all;cursor:pointer}
#ov text{paint-order:stroke fill;stroke-linejoin:round;dominant-baseline:auto}
#ov .hit:focus{outline:none}
#ov .hit:focus-visible>*:first-child{stroke:#fff;stroke-width:3px}
#ov .disp{font-family:var(--font-display);font-weight:400}
#ov .dim{opacity:.22;transition:opacity .45s}
#ov .lyr{transition:opacity .45s}
#ov .lyr.off{opacity:0;pointer-events:none}
#ov .lyr.off *{pointer-events:none !important}


@keyframes march{to{stroke-dashoffset:-48}}
@keyframes pulse{0%{opacity:.75;transform:scale(.6)}100%{opacity:0;transform:scale(2.4)}}
#ov .flow-live{animation:march 1.4s linear infinite}
#ov .pulse{transform-box:fill-box;transform-origin:center;animation:pulse 2.6s ease-out 4}
@media (prefers-reduced-motion:reduce){#ov .flow-live,#ov .pulse{animation:none}}
.no-motion #ov .flow-live,.no-motion #ov .pulse{animation:none}


#top{position:absolute;left:12px;right:12px;top:12px;display:flex;align-items:center;gap:12px;z-index:5;pointer-events:none}
#top>*{pointer-events:auto}
.brand{display:flex;align-items:center;gap:10px;background:var(--ui-bg);border:1px solid var(--ui-line);border-radius:var(--ui-radius);padding:8px 14px 8px 10px;backdrop-filter:blur(8px)}
.brand-mark{width:26px;height:26px;border-radius:7px;background:radial-gradient(circle at 50% 50%,var(--yellow) 0 22%,transparent 23%),repeating-radial-gradient(circle at 50% 50%,transparent 0 5px,rgba(230,231,232,.55) 5px 6px);border:1px solid rgba(255,255,255,.12)}
.brand-text{display:flex;flex-direction:column;line-height:1.15}
.brand-text strong{font-size:14px;letter-spacing:-.01em}
.brand-text span{font-size:12px;color:var(--ui-dim)}
#case-select{pointer-events:auto;font:inherit;font-size:12px;color:var(--ui-dim);background:transparent;border:0;border-bottom:1px dashed rgba(230,231,232,.25);padding:0 2px 1px 0;margin:0;max-width:230px;cursor:pointer;color-scheme:dark}
#case-select:hover,#case-select:focus-visible{color:var(--ui-ink);border-bottom-color:var(--yellow)}
#case-sel-tools{display:none}

.p-photo .ph{display:block;position:relative;width:100%;padding:0;margin:0;border:1px solid var(--ui-line);border-radius:8px;overflow:hidden;background:rgba(255,255,255,.04);cursor:zoom-in}
.p-photo .ph img{display:block;width:100%;height:100%;object-fit:cover}
.p-photo .ph:focus-visible{outline:2px solid var(--yellow);outline-offset:2px}
.p-photo .ph-wait{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:12px;color:var(--ui-faint)}
.p-photo .p-note{margin-top:6px}
#lightbox{position:fixed;inset:0;z-index:40;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;padding:56px 16px 24px;background:rgba(4,5,5,.92);cursor:zoom-out}
#lightbox[hidden]{display:none}
#lightbox img{display:block;width:min(100%,1100px);max-height:calc(100% - 60px);object-fit:contain;border-radius:8px;box-shadow:0 18px 50px rgba(0,0,0,.6)}
#lightbox .lb-cap{font-size:13px;line-height:1.5;color:var(--ui-dim);text-align:center;max-width:760px}
#lightbox .lb-close{position:absolute;top:12px;right:12px;width:44px;height:44px;border-radius:10px;border:1px solid var(--ui-line);background:var(--ui-bg-solid);color:var(--ui-ink);font-size:22px;cursor:pointer}

#top:has(.tools.open){z-index:13}
.tools.open{max-height:calc(100% - 70px);max-height:calc(100dvh - 70px);overflow-y:auto}
.modes{display:flex;background:var(--ui-bg);border:1px solid var(--ui-line);border-radius:var(--ui-radius);padding:3px;backdrop-filter:blur(8px)}
.modes button{border:0;background:none;padding:7px 14px;border-radius:7px;font-size:13px;color:var(--ui-dim);cursor:pointer}
.modes button[aria-selected="true"]{background:rgba(248,237,48,.14);color:var(--yellow);font-weight:600}
.modes button:hover{color:var(--ui-ink)}
.tools{margin-left:auto;display:flex;align-items:center;gap:8px}
.sel{display:flex;align-items:center;gap:6px;background:var(--ui-bg);border:1px solid var(--ui-line);border-radius:var(--ui-radius);padding:4px 6px 4px 10px;font-size:12px;color:var(--ui-dim);backdrop-filter:blur(8px)}
.sel select{background:transparent;border:0;color:var(--ui-ink);font-size:13px;padding:4px 2px;max-width:220px;cursor:pointer}
.sel select option{background:#111}
.tbtn{background:var(--ui-bg);border:1px solid var(--ui-line);border-radius:var(--ui-radius);padding:8px 13px;font-size:13px;cursor:pointer;backdrop-filter:blur(8px)}
a.tbtn{color:inherit;text-decoration:none;display:inline-block}
.tbtn:hover{border-color:rgba(255,255,255,.22)}
.tbtn[aria-pressed="true"]{color:var(--yellow);border-color:rgba(248,237,48,.4)}
.tbtn.primary{background:var(--yellow);color:#111;border-color:var(--yellow);font-weight:700}


#layers{position:absolute;left:12px;top:74px;z-index:4;width:208px;background:var(--ui-bg);border:1px solid var(--ui-line);border-radius:var(--ui-radius);backdrop-filter:blur(8px);overflow:hidden}
.layers-head{width:100%;text-align:left;background:none;border:0;padding:10px 12px;font-size:12px;font-weight:600;color:var(--ui-dim);cursor:pointer;display:flex;justify-content:space-between}
#layers.collapsed #layer-list{display:none}
#layers.collapsed .caret{transform:rotate(-90deg)}
#layer-list{padding:0 6px 8px;max-height:calc(100vh - 200px);overflow:auto}
.lg{margin-top:6px}
.lg-title{font-size:11px;color:var(--ui-faint);padding:6px 6px 3px;letter-spacing:.02em}
.li{display:flex;align-items:center;gap:8px;padding:5px 6px;border-radius:6px;font-size:13px;cursor:pointer;user-select:none}
.li:hover{background:rgba(255,255,255,.05)}
.li input{position:absolute;opacity:0;width:1px;height:1px;pointer-events:none}
.li:focus-within{outline:1px solid rgba(248,237,48,.6)}
.li .sw{width:18px;height:12px;border-radius:3px;flex:none;position:relative;opacity:.35;transition:opacity .2s}
.li input:checked+.sw{opacity:1}
.li span.t{flex:1;color:var(--ui-dim)}
.li input:checked~span.t{color:var(--ui-ink)}
.li .tag{font-size:10px;color:var(--ui-faint);border:1px solid var(--ui-line);border-radius:4px;padding:0 4px}


#panel{position:absolute;right:12px;top:74px;bottom:12px;z-index:6;width:340px;background:var(--ui-bg);border:1px solid var(--ui-line);border-radius:var(--ui-radius);backdrop-filter:blur(10px);overflow:auto;padding:16px 16px 20px}
#panel[hidden]{display:none}
.panel-close{position:absolute;right:8px;top:6px;border:0;background:none;font-size:22px;color:var(--ui-dim);cursor:pointer;line-height:1}
.p-kicker{font-size:11px;color:var(--ui-faint);letter-spacing:.03em;margin-bottom:4px}
.p-title{font-family:var(--font-display);font-size:26px;line-height:1.15;margin:0 0 4px;color:var(--yellow);letter-spacing:-.01em}
.p-sub{font-size:13px;color:var(--ui-dim);margin-bottom:12px}
.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:12px 0}
.p-stat{background:rgba(255,255,255,.04);border:1px solid var(--ui-line);border-radius:8px;padding:9px 10px}
.p-stat b{display:block;font-size:20px;font-weight:700;letter-spacing:-.02em;font-variant-numeric:tabular-nums}
.p-stat span{font-size:11px;color:var(--ui-dim)}
.p-sec{margin-top:14px}
.p-sec h4{font-size:12px;color:var(--ui-dim);font-weight:600;margin:0 0 6px}
.p-list{list-style:none;margin:0;padding:0}
.p-list li{display:flex;justify-content:space-between;gap:8px;padding:7px 8px;border-radius:6px;font-size:13px;cursor:pointer}
.p-list li:hover{background:rgba(255,255,255,.05)}
.p-list li em{font-style:normal;color:var(--ui-dim);font-variant-numeric:tabular-nums;white-space:nowrap}
.p-list li .gap{color:#ff7a70}
.p-note{font-size:11px;color:var(--ui-faint);line-height:1.5;margin-top:10px}
.p-src{font-size:11px;color:var(--ui-faint);line-height:1.5;border-top:1px solid var(--ui-line);margin-top:14px;padding-top:10px}
.p-btn{margin-top:8px;width:100%;padding:9px;border-radius:8px;border:1px solid rgba(248,237,48,.4);background:rgba(248,237,48,.1);color:var(--yellow);font-weight:600;cursor:pointer}
.spark{width:100%;height:64px;display:block;margin-top:6px}
.badge{display:inline-block;font-size:10.5px;padding:1px 6px;border-radius:4px;border:1px solid var(--ui-line);color:var(--ui-dim);margin-right:4px}
.badge.m{border-color:rgba(157,201,187,.5);color:var(--mint)}
.badge.c{border-color:rgba(248,237,48,.4);color:var(--yellow)}
.badge.e{border-color:rgba(239,64,54,.45);color:#ff8a80}


#story{position:absolute;left:50%;bottom:18px;transform:translateX(-50%);z-index:6;width:min(760px,calc(100vw - 32px))}
#story[hidden]{display:none}
.story-card{background:rgba(10,13,12,.9);border:1px solid var(--ui-line);border-radius:14px;padding:16px 20px 12px;backdrop-filter:blur(12px);box-shadow:0 18px 50px rgba(0,0,0,.45)}
.story-kicker{font-size:12px;color:var(--mint);letter-spacing:.04em;margin-bottom:2px}
.story-title{font-family:var(--font-display);font-weight:400;font-size:30px;line-height:1.18;margin:0 0 6px;color:var(--yellow-head);letter-spacing:-.005em}
.story-caption{margin:0 0 10px;font-size:15px;line-height:1.6;color:#dfe3e1}
.story-numbers{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:10px}
.story-numbers .n{background:rgba(255,255,255,.05);border:1px solid var(--ui-line);border-radius:8px;padding:6px 10px;font-size:12px;color:var(--ui-dim)}
.story-numbers .n b{display:block;font-size:19px;color:var(--ui-ink);font-weight:700;font-variant-numeric:tabular-nums;letter-spacing:-.02em}
.story-numbers .n.warn b{color:#ff8a80}
.story-nav{display:flex;align-items:center;justify-content:space-between;gap:10px;border-top:1px solid var(--ui-line);padding-top:10px}
.story-nav button{width:36px;height:30px;border-radius:8px;border:1px solid var(--ui-line);background:rgba(255,255,255,.04);font-size:18px;cursor:pointer}
.story-nav button:hover{border-color:rgba(255,255,255,.25)}
.story-dots{display:flex;gap:6px;flex:1;justify-content:center;flex-wrap:wrap}
.story-dots button{width:auto;height:22px;padding:0 8px;font-size:11px;border-radius:11px;color:var(--ui-dim)}
.story-dots button[aria-current="step"]{background:rgba(248,237,48,.16);border-color:rgba(248,237,48,.5);color:var(--yellow)}


#timeline{position:absolute;left:50%;bottom:18px;transform:translateX(-50%);z-index:7;display:flex;align-items:center;gap:12px;background:var(--ui-bg);border:1px solid var(--ui-line);border-radius:12px;padding:10px 14px;width:min(640px,calc(100vw - 32px));backdrop-filter:blur(10px)}
#timeline[hidden]{display:none}
#timeline.lift{bottom:230px}
#tl-play{width:34px;height:34px;border-radius:50%;border:1px solid rgba(248,237,48,.45);background:rgba(248,237,48,.1);color:var(--yellow);cursor:pointer}
#tl-range{flex:1;accent-color:var(--yellow)}
.tl-meta{display:flex;flex-direction:column;min-width:150px;font-size:11px;color:var(--ui-dim)}
.tl-meta strong{font-size:15px;color:var(--ui-ink);font-variant-numeric:tabular-nums}


#export-menu{position:absolute;right:12px;top:66px;z-index:14;background:var(--ui-bg-solid);border:1px solid var(--ui-line);border-radius:var(--ui-radius);padding:10px;width:270px;box-shadow:0 14px 40px rgba(0,0,0,.5)}
#export-menu[hidden]{display:none}
.em-title{font-size:12px;color:var(--ui-dim);margin:2px 4px 8px}
#export-menu button{display:block;width:100%;text-align:left;background:rgba(255,255,255,.04);border:1px solid var(--ui-line);border-radius:8px;padding:9px 10px;margin-bottom:6px;font-size:13px;cursor:pointer}
#export-menu button:hover{border-color:rgba(248,237,48,.45)}
.em-note{font-size:11px;color:var(--ui-faint);margin:6px 4px 0;line-height:1.5}

#toast{position:absolute;left:50%;top:74px;transform:translateX(-50%);z-index:20;background:#111;border:1px solid rgba(248,237,48,.4);color:var(--ui-ink);padding:9px 14px;border-radius:9px;font-size:13px;box-shadow:0 10px 30px rgba(0,0,0,.5)}
#toast[hidden]{display:none}
#loading{position:absolute;inset:0;z-index:30;display:flex;flex-direction:column;gap:14px;align-items:center;justify-content:center;background:#050605;color:var(--ui-dim);font-size:14px;transition:opacity .5s}
#app:not(.is-loading) #loading{opacity:0;pointer-events:none}
#app:not(.is-loading) .spinner{animation:none}
.spinner{width:42px;height:42px;border-radius:50%;border:2px dashed rgba(230,231,232,.5);border-top-color:var(--yellow);animation:spin 1.6s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}

.maplibregl-ctrl-attrib{background:rgba(0,0,0,.45)!important;color:#aaa!important;font-size:10px!important}
.maplibregl-ctrl-attrib a{color:#ccc!important}
.maplibregl-ctrl-bottom-right{z-index:3}


.l-long{display:none}
.tbtn.more{display:none}

.mode-story #layers{display:none}
.presenting #top .tools,.presenting #top .brand{opacity:.25;transition:opacity .3s}
.presenting #top:hover .tools,.presenting #top:hover .brand{opacity:1}


.modes button,.tbtn,.sel span,.brand-text strong{white-space:nowrap}
@media (max-width:1500px){
  .sel>span{display:none}
  .sel select{max-width:200px}
  .brand-text span{max-width:190px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
}
@media (max-width:1180px){
  #top .tbtn.more{display:block;flex:none;min-width:44px;min-height:40px;font-size:18px;margin-left:auto}
  .tools{display:none}
  .tools.open{display:flex;flex-direction:column;align-items:stretch;position:fixed;top:64px;right:12px;width:300px;z-index:12;background:var(--ui-bg-solid);border:1px solid var(--ui-line);border-radius:12px;padding:10px;gap:8px;box-shadow:0 14px 40px rgba(0,0,0,.55)}
  .tools.open .tbtn,.tools.open .sel{min-height:40px;width:100%}
  .tools.open .sel>span{display:inline}
  .tools.open .sel select{max-width:none;flex:1}
  .tools.open .l-long{display:inline}
  .tools.open .l-short{display:none}
  .presenting #top .tools.open,.presenting #top .tbtn.more{opacity:1}
}
@media (max-width:760px){
  #top{left:8px;right:8px;top:8px;gap:6px;flex-wrap:nowrap;overflow-x:auto;scrollbar-width:none}
  #top::-webkit-scrollbar{display:none}
  .brand{padding:6px 8px;flex:none}
  .brand-text{display:none}
  .brand{padding:6px}
  .tools.open #case-sel-tools{display:flex}
  .modes{flex:none}
  .modes button{padding:6px 9px;font-size:12px}
  .tools{margin-left:0;flex:none;gap:6px}
  .sel{flex:none;padding:3px 4px 3px 8px}
  .sel select{max-width:120px;font-size:12px}
  .tbtn{padding:7px 9px;font-size:12px;white-space:nowrap}
  #layers{top:auto;bottom:10px;left:8px;width:170px}
  #layers:not(.collapsed) #layer-list{max-height:42vh}
  #panel{left:8px;right:8px;width:auto;top:auto;bottom:8px;height:58vh}
  #story{bottom:8px;width:calc(100vw - 16px)}
  .story-card{padding:12px 14px 10px}
  .story-title{font-size:21px}
  .story-caption{font-size:13.5px;line-height:1.55;margin-bottom:8px}
  .story-numbers .n{padding:5px 8px}
  .story-numbers .n b{font-size:16px}
  .story-dots{display:none}
  .story-nav button{width:48px;height:44px;font-size:22px}
  .story-card{max-height:44vh;overflow:auto}
  .modes button{min-height:44px}
  #timeline{bottom:8px;width:calc(100vw - 16px)}
  #export-menu{right:8px;left:8px;width:auto;top:56px}
  #top .tbtn.more{display:block;flex:none;min-width:44px;min-height:44px;font-size:18px;margin-left:auto}
  .presenting #top .tools.open,.presenting #top .tbtn.more{opacity:1}
  .tools.open .l-long{display:inline}
  .tools.open .l-short{display:none}
  #top{overflow:visible}
  .tools{display:none}
  .tools.open{display:flex;flex-direction:column;align-items:stretch;position:fixed;top:58px;right:8px;left:8px;width:auto;z-index:12;background:var(--ui-bg-solid);border:1px solid var(--ui-line);border-radius:12px;padding:10px;gap:8px;box-shadow:0 14px 40px rgba(0,0,0,.55)}
  .tools.open .tbtn,.tools.open .sel{min-height:44px;width:100%}
  .tools.open .sel select{max-width:none;flex:1}
}
.sel span{white-space:nowrap}
.story-kicker{display:flex;justify-content:space-between;gap:8px}
.story-count{color:var(--ui-dim);font-variant-numeric:tabular-nums}
.story-nav button:disabled{opacity:.3;cursor:default}
.bars{margin-top:8px;display:flex;flex-direction:column;gap:3px}
.bar-row{display:grid;grid-template-columns:36px 1fr 74px;align-items:center;gap:6px;font-size:11.5px;color:var(--ui-dim);font-variant-numeric:tabular-nums}
.bar-row .bt{height:8px;background:rgba(255,255,255,.05);border-radius:4px;overflow:hidden}
.bar-row .bt i{display:block;height:100%;background:rgba(157,201,187,.55);border-radius:4px}
.bar-row.hi .bt i{background:var(--yellow)}
.bar-row.hi{color:var(--ui-ink)}
.bar-row .bv{text-align:right}

.gapdoc h4{color:var(--ui-ink);font-size:13px}
.draft{display:block;width:100%;text-align:left;margin-top:8px;background:rgba(255,255,255,.04);border:1px dashed rgba(255,255,255,.18);border-radius:8px;padding:9px 10px;font-size:12px;line-height:1.55;color:#dfe3e1;cursor:copy}
.draft:hover{border-color:rgba(248,237,48,.5)}
.draft.copied{border-color:#9DC9BB;background:rgba(157,201,187,.12)}
.draft.copied::after{content:' — 복사됨';color:#9DC9BB;font-weight:600}

.ed{display:block;margin-top:10px}
.ed span{display:block;font-size:11px;color:var(--ui-dim);margin-bottom:4px}
.ed textarea{width:100%;resize:vertical;background:#070908;border:1px solid rgba(255,255,255,.14);border-radius:7px;color:var(--ui-ink);padding:7px 8px;font-size:13px;line-height:1.5;font-family:var(--font-body)}
.ed textarea:focus{outline:none;border-color:rgba(248,237,48,.55)}
#panel code{font-size:11px;background:rgba(255,255,255,.06);padding:0 4px;border-radius:3px}

.cmp{width:100%;border-collapse:collapse;font-size:12px;margin-top:8px;font-variant-numeric:tabular-nums}
.cmp th,.cmp td{padding:6px 5px;border-bottom:1px solid var(--ui-line);text-align:right;white-space:nowrap}
.cmp th:first-child,.cmp td:first-child{text-align:left;color:var(--ui-dim);white-space:normal}
.cmp th{font-weight:600;color:var(--ui-dim)}
.cmp .on{color:var(--yellow);background:rgba(248,237,48,.06)}
.cmp small{color:var(--ui-faint);margin-left:2px;font-size:10px}

.p-list.src li{cursor:default;align-items:flex-start}
.p-list.src small{color:var(--ui-dim);font-size:11px;line-height:1.45}
.notes{margin:0;padding-left:16px;font-size:12px;color:#cfd4d2;line-height:1.55}
.notes li{margin-bottom:5px}
.warnbox{margin:4px 0 10px;padding:9px 10px;border-radius:8px;border:1px solid rgba(239,64,54,.45);background:rgba(239,64,54,.1);font-size:12.5px;line-height:1.55;color:#ffd7d2}
.story-numbers .n.missing b{color:var(--ui-faint);font-size:14px}


#fx{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;mix-blend-mode:screen}

#ov .lyr.c,#ov #labels,#ov #page{transition:opacity .3s ease}
#ov.transit .lyr.c,#ov.transit #labels,#ov.transit #page{opacity:0 !important;transition:opacity .16s ease}
#ov.hold>g,#ov.hold .lyr{opacity:0 !important}

#ov [data-hit]{transition:filter .15s}
#ov [data-hit].hov{filter:url(#glow)}
#peek{position:fixed;left:0;top:0;z-index:15;pointer-events:none;min-width:150px;max-width:290px;background:rgba(10,13,12,.95);border:1px solid rgba(248,237,48,.32);border-radius:10px;padding:9px 11px;font-size:12px;line-height:1.5;color:var(--ui-ink);box-shadow:0 12px 30px rgba(0,0,0,.5);opacity:0;transition:opacity .14s ease;will-change:transform}
#peek.on{opacity:1}
#peek b{display:block;font-family:var(--font-display);font-weight:400;font-size:17px;line-height:1.2;color:var(--yellow);letter-spacing:-.01em;margin-bottom:2px}
#peek .k{color:var(--ui-faint);font-size:11px}
#peek .v{font-weight:700;font-variant-numeric:tabular-nums}
#peek em{font-style:normal;color:var(--ui-faint);font-weight:500;font-size:11px}
#peek .hint{margin-top:5px;color:var(--mint);font-size:11px}
#fx-note{position:absolute;left:12px;bottom:14px;z-index:4;display:flex;align-items:center;gap:7px;background:rgba(10,13,12,.82);border:1px solid var(--ui-line);border-radius:8px;padding:6px 10px;font-size:11.5px;color:var(--ui-dim);backdrop-filter:blur(6px)}
#fx-note[hidden]{display:none}
#fx-note i{width:7px;height:7px;border-radius:50%;background:var(--yellow);box-shadow:0 0 8px var(--yellow)}

.story-progress{height:3px;background:rgba(255,255,255,.08);border-radius:2px;margin:-4px 0 10px;overflow:hidden}
.story-progress i{display:block;height:100%;width:0;background:linear-gradient(90deg,var(--mint),var(--yellow));border-radius:2px;transition:width .6s cubic-bezier(.16,.84,.3,1)}
.story-timer{height:2px;margin-top:8px;background:rgba(255,255,255,.06);border-radius:2px;overflow:hidden}
.story-timer[hidden]{display:none}
.story-timer i{display:block;height:100%;background:var(--yellow);transform-origin:left center;transform:scaleX(0)}
#story-play[aria-pressed="true"]{color:var(--yellow);border-color:rgba(248,237,48,.5);background:rgba(248,237,48,.1)}

#tl-big{position:absolute;left:50%;translate:-50% 0;bottom:calc(100% + 12px);font-family:var(--font-display);font-size:clamp(34px,5vw,60px);line-height:1;color:rgba(248,237,48,.92);text-shadow:0 3px 0 #060303,0 0 24px rgba(0,0,0,.6);pointer-events:none;font-variant-numeric:tabular-nums;white-space:nowrap}
#tl-big.warn{color:#ff8a80}
#tl-big[hidden]{display:none}

#intro{position:absolute;inset:0;z-index:25;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:12px;padding:0 16px;background:radial-gradient(ellipse at center,rgba(5,6,5,.1) 0%,rgba(5,6,5,.5) 60%,rgba(5,6,5,.82) 100%);cursor:pointer;transition:opacity .6s ease}
#intro[hidden]{display:none}
#intro.out{opacity:0;pointer-events:none}
#intro .in-k{font-size:13px;letter-spacing:.5em;text-indent:.5em;color:var(--mint);animation:inUp .7s .1s both cubic-bezier(.16,.84,.3,1)}
#intro .in-t{font-family:var(--font-display);font-size:clamp(44px,8vw,104px);line-height:1.02;color:var(--yellow-head);letter-spacing:-.01em;text-shadow:0 4px 0 #060303,0 0 40px rgba(248,237,48,.25);animation:inUp .8s .25s both cubic-bezier(.16,.84,.3,1);text-wrap:balance}
#intro .in-line{width:min(420px,60vw);height:2px;background:linear-gradient(90deg,transparent,#EE2F2B,transparent);animation:inLine 1s .5s both cubic-bezier(.16,.84,.3,1)}
#intro .in-s{font-size:clamp(13px,1.6vw,17px);color:#e6e7e8;animation:inUp .7s .55s both cubic-bezier(.16,.84,.3,1)}
#intro .in-skip{position:absolute;bottom:28px;left:0;right:0;font-size:12px;color:var(--ui-faint);animation:inUp .6s 1s both}
@keyframes inUp{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}
@keyframes inLine{from{transform:scaleX(0);opacity:0}to{transform:scaleX(1);opacity:1}}
#top,#layers,#story .story-card{transition:transform .7s cubic-bezier(.16,.84,.3,1),opacity .6s ease}
#app.intro #top{transform:translateY(-140%);opacity:0}
#btn-back{display:none;position:absolute;left:50%;bottom:22px;transform:translateX(-50%);z-index:12;font-weight:700;padding:10px 18px;transition:transform .6s cubic-bezier(.2,.8,.2,1),opacity .6s}
body.embed #btn-back{display:block}
#app.intro #btn-back{transform:translate(-50%,180%);opacity:0}
#app.intro #layers{transform:translateX(-120%);opacity:0}
#app.intro #story .story-card{transform:translateY(140%);opacity:0}
@media (max-width:1180px){.mode-story #fx-note{bottom:auto;top:66px}}
@media (max-width:760px){#fx-note{left:8px;right:auto;top:60px;bottom:auto;font-size:11px;padding:5px 8px}#fx{mix-blend-mode:normal}}
@media (prefers-reduced-motion:reduce){#ov .lyr.c,#ov #labels,#ov #page,#top,#layers,#story .story-card,.story-progress i{transition:none}#intro{display:none}}
.no-motion #intro{display:none}

.no-motion *,.no-motion *::before,.no-motion *::after{animation-duration:.01ms !important;animation-iteration-count:1 !important;transition-duration:.01ms !important;transition-delay:0s !important}
@media (prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:.01ms !important;animation-iteration-count:1 !important;transition-duration:.01ms !important;transition-delay:0s !important;scroll-behavior:auto !important}}

